import{_t as e,it as t,n,rt as r}from"./chunks/framework.C1oW5ckO.js";var i=JSON.parse(`{"title":"Plugin API: evolution and migration","description":"Compatibility decisions, migration and SemVer policy","frontmatter":{"navigation":{"category":"Plugin API"},"title":"Plugin API: evolution and migration","description":"Compatibility decisions, migration and SemVer policy","editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/docs/plugin-api/api-evolution-and-migration.md"},"headers":[],"relativePath":"docs/plugin-api/api-evolution-and-migration.md","filePath":"docs/plugin-api/api-evolution-and-migration.md","lastUpdated":1792080313000}`),a={name:`docs/plugin-api/api-evolution-and-migration.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="api-evolution-and-migration" tabindex="-1">API evolution and migration <a class="header-anchor" href="#api-evolution-and-migration" aria-label="Permalink to “API evolution and migration”">​</a></h1><p>The v0.1.1 <code>@pumpkinmc/pumpkin-api-ts</code> API is the compatibility baseline. The <a href="./../../tools/pumpkin-api/docs/migration">migration guide</a> covers the package and build changes. The full <a href="../../tools/pumpkin-api/compatibility/v0.1.1.json">compatibility inventory</a> records the decision for every export, type, WIT declaration and operation. Facade behavior changes include command-suggestion errors reporting the requested handler ID, IPC rejection paths throwing descriptive <code>Error</code> objects, callback cleanup after unload or failed registration, and rejecting task tick values other than numbers or bigints at runtime. The migration guide describes their impact.</p><p>Replace imports from <code>@pumpkinmc/pumpkin-api-ts</code> with <code>@pumpkin-plugins/pumpkin-api</code>, add the new package as a runtime dependency, and use <code>pumpkin-plugins-build</code> from <code>@pumpkin-plugins/build</code> to build components and generate types. No old package or build-command alias is provided.</p><p>Before <code>1.0.0</code>, compatible fixes use patch versions; features and breaking changes use the next minor version, so a breaking change from <code>0.1.0</code> becomes <code>0.2.0</code>. Starting at <code>1.0.0</code>, breaking changes require a major version. Breaking commits use a Conventional Commit <code>!</code> marker or <code>BREAKING CHANGE</code> footer and include release notes plus migration steps.</p>`,4)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};